#!/usr/bin/env sh
# Seed the local development database (the compose "db" service).
# Idempotent. Creates a demo project. SMTP credentials are secrets generated by
# the server, create one in the UI (Settings) or via the API.
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
COMPOSE="docker compose -f $ROOT/deploy/docker-compose.yml"
[ -f "$ROOT/deploy/.env" ] && COMPOSE="$COMPOSE --env-file $ROOT/deploy/.env"

$COMPOSE exec -T db psql -v ON_ERROR_STOP=1 -U sandpost -d sandpost <<'SQL'
INSERT INTO instance_settings (key, value)
VALUES ('instance_name', 'Sandpost (dev)')
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO projects (slug, name) VALUES ('demo', 'Demo')
ON CONFLICT (slug) DO NOTHING;
SQL
echo "seed complete"
